"""Undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused
from binkeep.report import entry_lines


def _broken(message: str):
    return DataError("journal", message)


def _stacks(entries: list[dict]):
    done, undone, dropped = [], [], set()
    for e in entries:
        name = e["op"]
        if name in journal.OPS:
            dropped.update(o["seq"] for o in undone)
            undone.clear()
            done.append(e)
        elif name in ("undo", "redo"):
            source, dest = (done, undone) if name == "undo" else (undone, done)
            if not source or source[-1]["seq"] != e.get("target"):
                raise _broken(f"#{e['seq']}: {name} does not match the stacks")
            dest.append(source.pop())
    return done, undone, dropped


def _effects(entry: dict) -> list[dict]:
    effects = entry.get("effects")
    if not isinstance(effects, list):
        raise _broken(f"#{entry['seq']}: no effects")
    for item in effects:
        if not isinstance(item, dict) or not isinstance(item.get("bin"), str) \
                or not isinstance(item.get("before"), int) or isinstance(item.get("before"), bool):
            raise _broken(f"#{entry['seq']}: bad effects")
    return effects


def _targets(ctx, entry: dict) -> list[tuple[str, int]]:
    """Format 1 operation: (bin, signed change to take back), in the order to apply."""
    try:
        name = entry["op"]
        if name == "receive":
            units = entry["qty"]
            if entry.get("uom") == "pk":
                units *= ctx.items[entry["sku"]].pack_size
            return [(normalize(entry["bin"]), -units)]
        if name == "issue":
            return [(normalize(code), qty) for code, qty in reversed(entry["picks"])]
        if name == "move":
            return [(normalize(entry["to"]), -entry["qty"]), (normalize(entry["from"]), entry["qty"])]
    except (KeyError, TypeError, ValueError):
        pass
    raise _broken(f"#{entry['seq']}: bad format 1 line")


def _apply(ctx, store, sku: str, wanted, new_seq: int, name: str, target: dict) -> dict:
    """wanted: list of (bin, quantity or None, delta) applied in order."""
    for code, _, _ in wanted:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
    effects = []
    for code, quantity, delta in wanted:
        before = store.qty(sku, code)
        after = quantity if quantity is not None else before + delta
        store.set(sku, code, after, restore=True)
        effects.append({"bin": code, "before": before, "after": after})
    return journal.entry(new_seq, name, ctx.by, sku, target=target["seq"], effects=effects)


def run(ctx, name: str, steps: int) -> list[str]:
    entries = list(ctx.entries)
    done, undone, _ = _stacks(entries)
    store = ctx.store.copy()
    new, lines = [], []
    for _ in range(steps):
        seq = journal.next_seq(entries)
        if name == "undo":
            if not done:
                raise Refused("nothing-to-undo", "nothing to undo")
            target = done[-1]
            if target["op"] == "fix":
                raise Refused("barrier", "a fix cannot be undone")
            if target.get("v") == 2:
                wanted = [(item["bin"], item["before"], 0) for item in reversed(_effects(target))]
            elif target["op"] == "count":
                raise Refused("irreversible", "the quantity before the count is not known")
            else:
                wanted = [(code, None, delta) for code, delta in _targets(ctx, target)]
        else:
            if not undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            target = undone[-1]
            source = next((e for e in reversed(entries)
                           if e["op"] == "undo" and e.get("target") == target["seq"]), None)
            if source is None:
                raise _broken(f"#{target['seq']}: no undo line")
            wanted = [(item["bin"], item["before"], 0) for item in reversed(_effects(source))]
        entry = _apply(ctx, store, target["sku"], wanted, seq, name, target)
        entries.append(entry)
        new.append(entry)
        if name == "undo":
            undone.append(done.pop())
        else:
            done.append(undone.pop())
        lines.extend(entry_lines(entry)[:1])
        lines[-1] += f" (#{target['seq']} {target['op']})"
        lines.extend(entry_lines(entry)[1:])
    ctx.commit(store, new)
    return lines


def history(ctx, limit: int) -> list[str]:
    done, undone, dropped = _stacks(ctx.entries)
    undone_seqs = {e["seq"] for e in undone}
    lines = []
    operations = [e for e in ctx.entries if e["op"] in journal.OPS]
    for e in reversed(operations[-limit:]):
        if e["seq"] in undone_seqs:
            status = "undone"
        elif e["seq"] in dropped:
            status = "dropped"
        elif e["op"] == "fix":
            status = "barrier"
        else:
            status = "done"
        lines.append(f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {status}")
    return lines
